def mp_gdtrib(a, p, x, guess):
    a, p, x = mp.mpf(a), mp.mpf(p), mp.mpf(x)
    def func(b):
        result = mp.gammainc(b, 0, a*x, regularized=True) - p
        return result
    with mp.workdps(100):
        try:
            result = float(
                mp.findroot(
                    func,
                    guess,
                    verify=True,
                    tol=1e-30,
                )
            )
        except Exception:
            result = np.nan
    return result


